function validateBasket(basket, allowedCodes) {
  if (basket === null || typeof basket !== "object" || Array.isArray(basket)) {
    throw new TypeError("basket must be an object");
  }
  for (const key of Reflect.ownKeys(basket)) {
    if (typeof key !== "string" || key.length === 0 ||
        !Number.isInteger(basket[key]) || basket[key] < 1 ||
        (allowedCodes !== undefined && !allowedCodes.has(key))) {
      throw new TypeError("invalid basket entry");
    }
  }
}

function inventoryCodes(inventory) {
  if (!Array.isArray(inventory)) throw new TypeError("inventory must be an array");
  const codes = new Set();
  for (const product of inventory) {
    if (product === null || typeof product !== "object" || Array.isArray(product) ||
        typeof product.code !== "string" || product.code.length === 0 ||
        codes.has(product.code)) {
      throw new TypeError("invalid inventory");
    }
    codes.add(product.code);
  }
  return codes;
}

function copyBasket(basket) {
  const copy = {};
  for (const code of Object.getOwnPropertyNames(basket)) {
    Object.defineProperty(copy, code, {
      value: basket[code],
      writable: true,
      enumerable: true,
      configurable: true
    });
  }
  return copy;
}

function updateBasket(basket, action, inventory) {
  const codes = inventoryCodes(inventory);
  validateBasket(basket, codes);
  if (action === null || typeof action !== "object" || Array.isArray(action) ||
      typeof action.code !== "string" || !codes.has(action.code)) {
    throw new TypeError("invalid action");
  }

  const result = copyBasket(basket);
  const current = Object.prototype.hasOwnProperty.call(result, action.code)
    ? result[action.code]
    : 0;

