      if (!Number.isInteger(next)) throw new TypeError("invalid resulting quantity");
      Object.defineProperty(result, action.code, {
        value: next,
        writable: true,
        enumerable: true,
        configurable: true
      });
    } else {
      delete result[action.code];
    }
  } else if (action.type === "set") {
    if (!Number.isInteger(action.quantity) || action.quantity < 0) {
      throw new TypeError("quantity must be non-negative");
    }
    if (action.quantity === 0) {
      delete result[action.code];
    } else {
      Object.defineProperty(result, action.code, {
        value: action.quantity,
        writable: true,
        enumerable: true,
        configurable: true
      });
