"use strict";

const assert = require("node:assert/strict");
const api = require("./solution");
assert.deepStrictEqual(Object.keys(api).sort(), ["countUnits", "updateBasket"]);
const { updateBasket, countUnits } = api;

const inventory = [{ code: "A" }, { code: "B" }, { code: "C" }];
const basket = { A: 2, B: 1 };
const basketSnapshot = { ...basket };
const inventorySnapshot = inventory.map((item) => ({ ...item }));

const added = updateBasket(basket, { type: "add", code: "A", quantity: 3 }, inventory);
assert.deepStrictEqual(added, { A: 5, B: 1 });
assert.notStrictEqual(added, basket);
assert.deepStrictEqual(basket, basketSnapshot);
assert.deepStrictEqual(inventory, inventorySnapshot);

assert.deepStrictEqual(updateBasket(basket, { type: "add", code: "C", quantity: 1 }, inventory), { A: 2, B: 1, C: 1 });
assert.deepStrictEqual(updateBasket(basket, { type: "remove", code: "A", quantity: 1 }, inventory), { A: 1, B: 1 });
assert.deepStrictEqual(updateBasket(basket, { type: "remove", code: "A", quantity: 2 }, inventory), { B: 1 });
assert.deepStrictEqual(updateBasket(basket, { type: "remove", code: "A", quantity: 99 }, inventory), { B: 1 });
assert.deepStrictEqual(updateBasket(basket, { type: "remove", code: "C", quantity: 1 }, inventory), { A: 2, B: 1 });
assert.deepStrictEqual(updateBasket(basket, { type: "set", code: "A", quantity: 7 }, inventory), { A: 7, B: 1 });
assert.deepStrictEqual(updateBasket(basket, { type: "set", code: "A", quantity: 0 }, inventory), { B: 1 });

const emptyResult = updateBasket({}, { type: "set", code: "C", quantity: 0 }, inventory);
assert.deepStrictEqual(emptyResult, {});
assert.notStrictEqual(emptyResult, basket);
assert.strictEqual(countUnits({}), 0);
assert.strictEqual(countUnits({ C: 4, A: 2, B: 3 }), 9);

for (const invalidBasket of [null, [], "", 3, { A: 0 }, { A: -1 }, { A: 1.5 }, { A: NaN }, { A: Infinity }]) {
  assert.throws(() => countUnits(invalidBasket), TypeError);
}
assert.throws(() => updateBasket({ Z: 1 }, { type: "add", code: "A", quantity: 1 }, inventory), TypeError);

for (const invalidInventory of [null, {}, [null], [{}], [{ code: "" }], [{ code: 1 }], [{ code: "A" }, { code: "A" }]]) {
  assert.throws(() => updateBasket({}, { type: "add", code: "A", quantity: 1 }, invalidInventory), TypeError);
}

for (const invalidAction of [
  null,
  [],
  {},
  { type: "unknown", code: "A", quantity: 1 },
  { type: "add", code: "Z", quantity: 1 },
  { type: "add", code: "A", quantity: 0 },
  { type: "add", code: "A", quantity: -1 },
  { type: "add", code: "A", quantity: 1.5 },
  { type: "remove", code: "A", quantity: 0 },
  { type: "set", code: "A", quantity: -1 },
  { type: "set", code: "A", quantity: 1.5 },
  { type: "set", code: 1, quantity: 1 },
  { type: "set", quantity: 1 }
]) {
  assert.throws(() => updateBasket(basket, invalidAction, inventory), TypeError);
}

